create table public.student_assignments (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete restrict, student_id uuid not null references public.students(id) on delete restrict, classroom_id uuid not null references public.classrooms(id) on delete restrict, academic_year_id uuid not null references public.academic_years(id) on delete restrict, semester_id uuid not null references public.semesters(id) on delete restrict, is_active boolean not null default true, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(tenant_id,student_id,semester_id));
create index student_assignments_tenant_idx on public.student_assignments(tenant_id); alter table public.student_assignments enable row level security; revoke all on public.student_assignments from anon,authenticated; create policy student_assignments_select_tenant on public.student_assignments for select to authenticated using(tenant_id=public.current_tenant_id());
insert into public.permissions(code,name,description) values ('student_assignments.read','Read student assignments','View student assignments'),('student_assignments.create','Create student assignments','Assign students'),('student_assignments.update','Update student assignments','Maintain student assignments'),('student_assignments.delete','Delete student assignments','Remove student assignments') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in ('OWNER','PRINCIPAL','STAFF') and p.code like 'student_assignments.%' on conflict do nothing;
